from sympy import cos, log, sin, symbols, tan, sec
from sympy.integrals.manualintegrate import manualintegrate
x = symbols('x')

def integrate_all(cases):
    out = []
    for f in cases:
        try:
            out.append(str(manualintegrate(f, x)))
        except Exception as exc:
            out.append('raised ' + type(exc).__name__)
    return out
